/* xterm.js stub — functional fallback until real file is downloaded.
 * To get real xterm, run on your Kali machine:
 *   curl -sL https://cdn.jsdelivr.net/npm/xterm@5.3.0/lib/xterm.min.js -o static/vendor/xterm.min.js
 *   curl -sL https://cdn.jsdelivr.net/npm/xterm@5.3.0/css/xterm.css   -o static/vendor/xterm.min.css
 */
(function(){
  if (window.Terminal) return; // real xterm already loaded
  function Terminal(opts) {
    this.opts = opts || {};
    this._lines = [];
    this._container = null;
    this._listeners = {};
  }
  Terminal.prototype.open = function(el) {
    this._container = el;
    el.style.background = '#040608';
    el.style.color = '#e2e8f0';
    el.style.fontFamily = "'JetBrains Mono', monospace";
    el.style.fontSize = '13px';
    el.style.padding = '8px';
    el.style.overflowY = 'auto';
    el.style.whiteSpace = 'pre-wrap';
    el.style.wordBreak = 'break-all';
    this._out = document.createElement('div');
    el.appendChild(this._out);
  };
  Terminal.prototype.write = function(data) {
    if (!this._out) return;
    // Strip basic ANSI escape codes for display
    var clean = data.replace(/\x1b\[[0-9;]*[mGKHFABCDJr]/g,'').replace(/\r/g,'');
    this._out.textContent += clean;
    if (this._container) this._container.scrollTop = this._container.scrollHeight;
  };
  Terminal.prototype.writeln = function(data) { this.write(data + '\n'); };
  Terminal.prototype.clear = function() { if (this._out) this._out.textContent = ''; };
  Terminal.prototype.dispose = function() { if (this._container) this._container.innerHTML = ''; };
  Terminal.prototype.onData = function(cb) { this._listeners.data = cb; };
  Terminal.prototype.resize = function() {};
  Terminal.prototype.reset = function() {};
  window.Terminal = Terminal;
  console.info('[Platform] xterm stub active — for real PTY terminal run: curl -sL https://cdn.jsdelivr.net/npm/xterm@5.3.0/lib/xterm.min.js -o static/vendor/xterm.min.js');
})();
